package com.bidx.servlet;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import jakarta.servlet.*;import java.io.*;import java.math.*;import java.time.*;import com.bidx.model.*;import com.bidx.service.*;import com.bidx.repository.*;
class AuctionListServletImpl extends BaseServlet {private final AuctionService s=new AuctionService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setAttribute("auctions",s.browse(r.getParameter("q"),r.getParameter("category"),r.getParameter("status"),r.getParameter("sort")));r.setAttribute("home",r.getServletPath().equals("/"));view(r,p,"auction/list");}}
class AuctionDetailsServletImpl extends BaseServlet {private final AuctionService s=new AuctionService();private final BidService b=new BidService();private final UserRepository users=new UserRepository();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{Auction a=s.find(r.getParameter("id"));if(a==null){p.sendError(404);return;}java.util.List<Bid> history=b.history(a.id);java.util.Map<String,String> bidderNames=new java.util.HashMap<>();for(Bid bid:history){User user=users.find(bid.bidderId);bidderNames.put(bid.bidderId,user==null?"Member":user.username);}User winner=a.winnerId==null||a.winnerId.isBlank()?null:users.find(a.winnerId);r.setAttribute("auction",a);r.setAttribute("bids",history);r.setAttribute("bidderNames",bidderNames);r.setAttribute("winnerName",winner==null?"":winner.username);r.setAttribute("minimum",a.currentHighestBid.add(a.minimumIncrement));view(r,p,"auction/detail");}}
class CreateAuctionServletImpl extends BaseServlet {private final AuctionService s=new AuctionService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{view(r,p,"auction/create");}protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{try{Auction a=new Auction();a.title=r.getParameter("title");a.description=r.getParameter("description");a.category=r.getParameter("category");a.condition=r.getParameter("condition");a.notes=r.getParameter("notes");a.imagePath="";a.startingPrice=new BigDecimal(r.getParameter("startingPrice"));a.minimumIncrement=new BigDecimal(r.getParameter("increment"));a.startAt=LocalDateTime.parse(r.getParameter("startAt"));a.endAt=LocalDateTime.parse(r.getParameter("endAt"));s.create(a,user(r).id);flash(r,"Auction created successfully.","success");p.sendRedirect(r.getContextPath()+"/my-auctions");}catch(Exception e){flash(r,e.getMessage()==null?"Please check the auction details.":e.getMessage(),"danger");p.sendRedirect(r.getContextPath()+"/auction/create");}}}
class PlaceBidServletImpl extends BaseServlet {private final BidService s=new BidService();protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{String id=r.getParameter("auctionId");try{s.place(id,user(r).id,r.getParameter("amount"));flash(r,"Bid placed successfully.","success");}catch(IllegalArgumentException e){flash(r,e.getMessage(),"danger");}p.sendRedirect(r.getContextPath()+"/auction?id="+id);}}
